e":"paragraph","content":[{"type":"text","text":"Anonymous audience measurement (no personal data) — legitimate interest (art. 6.1.f), with the option to opt out at any time via the banner or \"Do Not Track\" signals."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"AI assistant, where applicable — consent (art. 6.1.a), revocable at any time."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Subprocessors"}]},{"type":"paragraph","content":[{"type":"text","text":"Your data is processed by providers based in the European Union, bound by a data processing agreement (DPA):"}]}]}$tiptap$::jsonb)
