values ('confidentialite-suite', 'en', 'Privacy Policy (continued)', $tiptap${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Retention periods"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Contact requests: up to 36 months after the last exchange, then anonymized or deleted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anti-abuse technical logs: 90 days maximum."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Administration audit log: retained for security purposes."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. Your rights"}]},{"type":"paragraph","content":[{"type":"text","text":"You have the right to access, rectify, erase, restrict, object to, and port your data. Write to us at "},{"type":"text","text":"bonjour@solive.pro","marks":[{"type":"link","attrs":{"href":"mailto:bonjour@solive.pro"}}]},{"type":"text","text":"; we reply within 30 days. You can also file a complaint with the Belgian Data Protection Authority (APD) — "},{"type":"text","text":"autoriteprotectiondonnees.be","marks":[{"type":"link","attrs":{"href":"https://www.autoriteprotectiondonnees.be"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. Transfers outside the EU"}]},{"type":"paragraph","content":[{"type":"text","text":"No transfer of your personal data outside the European Union takes place in connection with the operation of the site."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. Security"}]},{"type":"paragraph","content":[{"type":"text","text":"Encryption in transit, database-level access-policy isolation (RLS), strong authentication (MFA), and an administration-side audit log."}]}]}$tiptap$::jsonb)
